"use strict";
import SelectOption from "pages/Locks/common/SelectOption";
import { Flex, Text, useSporeColors } from "ui/src";
import { Checkbox } from "ui/src/components/checkbox/Checkbox";
import { formatABXAmount, formatTimeUntilUnlock } from "utils/lockCalculations";
import RelayStrategy from "./RelayStrategy";
import TopTitleAndCreateLock from "./TopTitleAndCreateLock";
export default function SelectYourLock({
  lockOptions,
  selectedLockId,
  onSelectLock,
  selectedLock,
  relayOptions,
  selectedRelayId,
  onSelectRelay,
  selectedRelay,
  isLoading,
  termsAccepted,
  onChangeTerms
}) {
  const colors = useSporeColors();
  const lockLabelMap = new Map(lockOptions.map((option) => [option.label, option.value]));
  const relayLabelMap = new Map(relayOptions.map((option) => [option.label, option.value]));
  const hasLockOptions = lockOptions.length > 0;
  const lockPlaceholder = hasLockOptions ? "Select a lock" : "No eligible locks";
  const shouldShowLockPlaceholder = hasLockOptions && !selectedLockId;
  const lockLabels = hasLockOptions ? shouldShowLockPlaceholder ? [lockPlaceholder, ...lockOptions.map((option) => option.label)] : lockOptions.map((option) => option.label) : [lockPlaceholder];
  const relayLabels = relayOptions.length > 0 ? relayOptions.map((option) => option.label) : ["No active ABX Vaults"];
  const selectedLockLabel = lockOptions.find((option) => option.value === selectedLockId)?.label ?? (shouldShowLockPlaceholder ? lockPlaceholder : lockLabels[0] ?? lockPlaceholder);
  const selectedRelayLabel = relayOptions.find((option) => option.value === selectedRelayId)?.label ?? relayLabels[0] ?? "No active ABX Vaults";
  const handleLockSelect = (label) => {
    const lockId = lockLabelMap.get(label);
    if (lockId) {
      onSelectLock(lockId);
    }
  };
  const handleRelaySelect = (label) => {
    const relayId = relayLabelMap.get(label);
    if (relayId) {
      onSelectRelay(relayId);
    }
  };
  return <Flex
    flexDirection="column"
    backgroundColor={"$surface2"}
    p={"$spacing16"}
    borderRadius={"$rounded12"}
    gap={"$gap36"}
    borderWidth={1}
    borderColor={"$surface3"}
    $lg={{ gap: "$spacing24" }}
    style={{
      background: `linear-gradient(180deg, ${colors.surface2.variable} 0%, transparent 100%)`
    }}
  >
      <TopTitleAndCreateLock />

      <Flex flexDirection="column" gap="$gap12">
        <Text variant="buttonLabel3">Select Lock</Text>
        <SelectOption options={lockLabels} defaultOption={selectedLockLabel} onSelect={handleLockSelect} />
        {selectedLock ? <Flex
    borderWidth={1}
    borderColor="$surface3"
    borderRadius="$rounded12"
    p="$spacing12"
    flexDirection="column"
    gap="$gap8"
  >
            <Text variant="body3" color="$neutral2">
              Locked Amount
            </Text>
            <Text variant="body2">{formatABXAmount(BigInt(selectedLock.amount))} ABX</Text>
            <Text variant="body3" color="$neutral2">
              Unlock Date
            </Text>
            <Text variant="body2">
              {selectedLock.permanent ? "Permanent lock" : formatTimeUntilUnlock(selectedLock.lockEnd)}
            </Text>
          </Flex> : <Text variant="body4" color="$neutral3">
            {isLoading ? "Loading available locks\u2026" : hasLockOptions ? "Select a lock to deposit." : "No eligible locks available for ABX Vault deposit."}
          </Text>}
      </Flex>

      <RelayStrategy
    relayOptions={relayLabels}
    selectedRelayLabel={selectedRelayLabel}
    onSelectRelay={handleRelaySelect}
    selectedRelay={selectedRelay}
    isLoading={isLoading}
  />

      <Flex
    row
    gap="$gap12"
    px="$spacing12"
    py="$spacing16"
    borderRadius="$rounded12"
    borderWidth={1}
    borderColor={termsAccepted ? "$surface3" : "$surface2"}
    backgroundColor={termsAccepted ? "$surface2" : "$slate"}
    alignItems="center"
    onPress={() => onChangeTerms(!termsAccepted)}
  >
        <Checkbox
    size="$icon.16"
    checked={termsAccepted}
    onCheckedChange={(value) => onChangeTerms(value === true)}
    onPress={(event) => {
      event?.stopPropagation?.();
    }}
  />
        <Text variant="body3">
          I acknowledge that once I deposit my lock into an ABX Vault strategy, the lock&apos;s unlock date will be
          extended to the maximum duration, and rewards will be managed by the vault.
        </Text>
      </Flex>
    </Flex>;
}
