  const { depositMap, isLoading: depositsLoading, refetch: refetchManagedStatus } = useManagedDeposits(userLocks);
  const { hasVoted, refetch: refetchVotes } = useVotedLocks(userLocks);
  const { data: relays = [], isLoading: relaysLoading } = useManagedVeABXRelays(true, resolvedChainId);
  const relayIds = useMemo(() => relays.map((relay) => relay.id), [relays]);
  const { statusMap: relayStatusMap } = useRelayStatuses(relayIds);
